import React, { useState, useEffect } from "react";
import "./RouteForm.css";

const RouteForm = ({
  onSave,
  onCancel,
  isVisible,
  route = null,
  isEditing = false,
}) => {
  const [formData, setFormData] = useState({
    nombre: "",
    tipo: "peatonal",
    distancia: 0,
    tiempo_estimado: 0,
    geometria: null,
    puntos_ruta: [],
  });

  const [manualOrigen, setManualOrigen] = useState({
    lat: "",
    lng: "",
    nombre: "",
  });
  const [manualDestino, setManualDestino] = useState({
    lat: "",
    lng: "",
    nombre: "",
  });

  useEffect(() => {
    if (route && isEditing) {
      setFormData({
        nombre: route.nombre || "",
        tipo: route.tipo || "peatonal",
        distancia: route.distancia || 0,
        tiempo_estimado: route.tiempo_estimado || 0,
        geometria: route.geometria || null,
        puntos_ruta: route.puntos_ruta || [],
      });

      // Cargar datos existentes en los campos manuales
      if (route.puntos_ruta && route.puntos_ruta.length >= 2) {
        const puntoOrigen = route.puntos_ruta.find(
          (p) => p.tipo_punto === "inicio" || p.orden === 1
        );
        const puntoDestino = route.puntos_ruta.find(
          (p) => p.tipo_punto === "fin" || p.orden === 2
        );

        if (puntoOrigen && puntoOrigen.coordenadas) {
          const [lng, lat] = puntoOrigen.coordenadas.coordinates;
          setManualOrigen({
            lat: lat.toString(),
            lng: lng.toString(),
            nombre: puntoOrigen.nombre_punto || puntoOrigen.descripcion || "",
          });
        }

        if (puntoDestino && puntoDestino.coordenadas) {
          const [lng, lat] = puntoDestino.coordenadas.coordinates;
          setManualDestino({
            lat: lat.toString(),
            lng: lng.toString(),
            nombre: puntoDestino.nombre_punto || puntoDestino.descripcion || "",
          });
        }
      }
    } else {
      setFormData({
        nombre: "",
        tipo: "peatonal",
        distancia: 0,
        tiempo_estimado: 0,
        geometria: null,
        puntos_ruta: [],
      });
      setManualOrigen({ lat: "", lng: "", nombre: "" });
      setManualDestino({ lat: "", lng: "", nombre: "" });
    }
  }, [route, isEditing]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleNumberChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: parseFloat(value) || 0,
    }));
  };

  // ✅ Función para calcular distancia entre coordenadas
  const calculateDistance = (lat1, lon1, lat2, lon2) => {
    const R = 6371e3; // Radio de la Tierra en metros
    const φ1 = (lat1 * Math.PI) / 180;
    const φ2 = (lat2 * Math.PI) / 180;
    const Δφ = ((lat2 - lat1) * Math.PI) / 180;
    const Δλ = ((lon2 - lon1) * Math.PI) / 180;

    const a =
      Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
      Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    return Math.round(R * c);
  };

  // ✅ Calcular ruta usando coordenadas manuales
  const handleCalculateRoute = () => {
    if (
      !manualOrigen.lat ||
      !manualOrigen.lng ||
      !manualDestino.lat ||
      !manualDestino.lng
    ) {
      alert("Por favor ingresa todas las coordenadas");
      return;
    }

    const latOrigen = parseFloat(manualOrigen.lat);
    const lngOrigen = parseFloat(manualOrigen.lng);
    const latDestino = parseFloat(manualDestino.lat);
    const lngDestino = parseFloat(manualDestino.lng);

    // Validar coordenadas
    if (
      isNaN(latOrigen) ||
      isNaN(lngOrigen) ||
      isNaN(latDestino) ||
      isNaN(lngDestino)
    ) {
      alert("Por favor ingresa coordenadas válidas");
      return;
    }

    if (
      latOrigen < -90 ||
      latOrigen > 90 ||
      latDestino < -90 ||
      latDestino > 90
    ) {
      alert("La latitud debe estar entre -90 y 90 grados");
      return;
    }

    if (
      lngOrigen < -180 ||
      lngOrigen > 180 ||
      lngDestino < -180 ||
      lngDestino > 180
    ) {
      alert("La longitud debe estar entre -180 y 180 grados");
      return;
    }

    const geometria = {
      type: "LineString",
      coordinates: [
        [lngOrigen, latOrigen],
        [lngDestino, latDestino],
      ],
    };

    // Calcular distancia
    const distancia = calculateDistance(
      latOrigen,
      lngOrigen,
      latDestino,
      lngDestino
    );
    const tiempo_estimado = Math.round(distancia / 80); // 1.3 m/s caminata

    setFormData((prev) => ({
      ...prev,
      geometria,
      distancia,
      tiempo_estimado,
      puntos_ruta: [
        {
          orden: 1,
          tipo_punto: "inicio",
          descripcion:
            manualOrigen.nombre ||
            `Origen (${latOrigen.toFixed(6)}, ${lngOrigen.toFixed(6)})`,
          nombre_punto: manualOrigen.nombre || "Punto de Origen",
          coordenadas: {
            type: "Point",
            coordinates: [lngOrigen, latOrigen],
          },
        },
        {
          orden: 2,
          tipo_punto: "fin",
          descripcion:
            manualDestino.nombre ||
            `Destino (${latDestino.toFixed(6)}, ${lngDestino.toFixed(6)})`,
          nombre_punto: manualDestino.nombre || "Punto de Destino",
          coordenadas: {
            type: "Point",
            coordinates: [lngDestino, latDestino],
          },
        },
      ],
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!formData.nombre || !formData.geometria) {
      alert("Nombre y ruta calculada son requeridos");
      return;
    }

    onSave(formData);
  };

  // ✅ Función para limpiar el formulario
  const handleClearForm = () => {
    setFormData({
      nombre: "",
      tipo: "peatonal",
      distancia: 0,
      tiempo_estimado: 0,
      geometria: null,
      puntos_ruta: [],
    });
    setManualOrigen({ lat: "", lng: "", nombre: "" });
    setManualDestino({ lat: "", lng: "", nombre: "" });
  };

  if (!isVisible) return null;

  return (
    <div className="route-form-overlay">
      <div className="route-form-container">
        <div className="route-form-header">
          <h3>{isEditing ? "✏️ Editar Ruta" : "➕ Crear Nueva Ruta"}</h3>
          <button className="close-btn" onClick={onCancel}>
            ×
          </button>
        </div>

        <form onSubmit={handleSubmit} className="route-form">
          <div className="form-group">
            <label>Nombre de la Ruta *</label>
            <input
              type="text"
              name="nombre"
              value={formData.nombre}
              onChange={handleInputChange}
              placeholder="Ej: Ruta desde Punto A hasta Punto B"
              required
            />
          </div>

          <div className="form-group">
            <label>Tipo de Ruta</label>
            <select
              name="tipo"
              value={formData.tipo}
              onChange={handleInputChange}>
              <option value="peatonal">Peatonal</option>
              <option value="vehicular">Vehicular</option>
              <option value="accesible">Accesible</option>
            </select>
          </div>

          <div className="route-calculation-section">
            <h4>🗺️ Definir Puntos de la Ruta</h4>
            <p className="section-description">
              Ingresa las coordenadas del punto de origen y destino
            </p>

            {/* Punto de Origen */}
            <div className="coordinate-inputs">
              <h5>📍 Punto de Origen</h5>
              <div className="coord-fields">
                <div className="coord-field">
                  <label>Latitud *</label>
                  <input
                    type="number"
                    step="any"
                    placeholder="Ej: -29.953216"
                    value={manualOrigen.lat}
                    onChange={(e) =>
                      setManualOrigen((prev) => ({
                        ...prev,
                        lat: e.target.value,
                      }))
                    }
                  />
                </div>
                <div className="coord-field">
                  <label>Longitud *</label>
                  <input
                    type="number"
                    step="any"
                    placeholder="Ej: -71.338594"
                    value={manualOrigen.lng}
                    onChange={(e) =>
                      setManualOrigen((prev) => ({
                        ...prev,
                        lng: e.target.value,
                      }))
                    }
                  />
                </div>
              </div>
              <div className="coord-name-field">
                <label>Nombre del punto (opcional)</label>
                <input
                  type="text"
                  placeholder="Ej: Entrada Principal, Plaza Central, etc."
                  value={manualOrigen.nombre || ""}
                  onChange={(e) =>
                    setManualOrigen((prev) => ({
                      ...prev,
                      nombre: e.target.value,
                    }))
                  }
                />
              </div>
            </div>

            {/* Punto de Destino */}
            <div className="coordinate-inputs">
              <h5>🎯 Punto de Destino</h5>
              <div className="coord-fields">
                <div className="coord-field">
                  <label>Latitud *</label>
                  <input
                    type="number"
                    step="any"
                    placeholder="Ej: -29.952456"
                    value={manualDestino.lat}
                    onChange={(e) =>
                      setManualDestino((prev) => ({
                        ...prev,
                        lat: e.target.value,
                      }))
                    }
                  />
                </div>
                <div className="coord-field">
                  <label>Longitud *</label>
                  <input
                    type="number"
                    step="any"
                    placeholder="Ej: -71.337891"
                    value={manualDestino.lng}
                    onChange={(e) =>
                      setManualDestino((prev) => ({
                        ...prev,
                        lng: e.target.value,
                      }))
                    }
                  />
                </div>
              </div>
              <div className="coord-name-field">
                <label>Nombre del punto (opcional)</label>
                <input
                  type="text"
                  placeholder="Ej: Salida Secundaria, Estacionamiento, etc."
                  value={manualDestino.nombre || ""}
                  onChange={(e) =>
                    setManualDestino((prev) => ({
                      ...prev,
                      nombre: e.target.value,
                    }))
                  }
                />
              </div>
            </div>

            <button
              type="button"
              className="calculate-btn"
              onClick={handleCalculateRoute}
              disabled={
                !manualOrigen.lat ||
                !manualOrigen.lng ||
                !manualDestino.lat ||
                !manualDestino.lng
              }>
              🧮 Calcular Ruta
            </button>
          </div>

          {formData.geometria && (
            <div className="route-details">
              <h4>📊 Detalles de la Ruta Calculada</h4>

              <div className="route-stats">
                <div className="stat-item">
                  <span className="stat-label">Distancia:</span>
                  <span className="stat-value">
                    {formData.distancia} metros
                  </span>
                </div>
                <div className="stat-item">
                  <span className="stat-label">Tiempo estimado:</span>
                  <span className="stat-value">
                    {formData.tiempo_estimado} minutos
                  </span>
                </div>
              </div>

              <div className="route-points">
                <h5>Puntos de la Ruta:</h5>
                {formData.puntos_ruta.map((punto, index) => (
                  <div key={index} className="route-point">
                    <span className="point-order">{punto.orden}.</span>
                    <span className="point-desc">{punto.descripcion}</span>
                    <span className="point-type">{punto.tipo_punto}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="form-actions">
            <button
              type="button"
              onClick={handleClearForm}
              className="clear-btn"
              disabled={!formData.nombre && !formData.geometria}>
              🗑️ Limpiar
            </button>
            <button type="button" onClick={onCancel} className="cancel-btn">
              Cancelar
            </button>
            <button
              type="submit"
              className="save-btn"
              disabled={!formData.geometria}>
              {isEditing ? "Actualizar" : "Crear"} Ruta
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default RouteForm;
